import * as M from './model.js';
import * as A from './academic-year.js';
export const ROLES=['학급문고 정리','자료 나누기','분실물 정리','책상 주변 정리','바닥 휴지 줍기','게시물 정리','모둠 준비물 정리','공용 교구 수량 확인','화분 살피기','실내화 정리','전등 확인 알림','오늘 일정 안내'];
export function data(state){return state.teacherPlanner??={entries:[],weeks:{},workPlans:[]};}
const live=e=>!['취소','불참','완료'].includes(e.status);
const overlap=(a,b)=>a.day===b.day&&a.start<b.end&&b.start<a.end;
export function upsert(state,entry){const d=data(state),id=entry.id||`plan-${entry.day}-${entry.start}-${entry.title.replace(/\s/g,'')}`;const prior=d.entries.find(e=>e.id===id);if(prior){Object.assign(prior,entry,{id});return prior;}const e={status:'예정',response:'미응답',note:'',created:M.stamp(state),...entry,id};d.entries.push(e);return e;}
function invitation(state,channel,sender,personId,entry){if(entry.day>=M.demoDays(state)||state.academic&&!A.schoolDay(state,entry.day))return;const id=`plan-${entry.day}-${entry.start}-${entry.title.replace(/\s/g,'')}`;if(data(state).entries.some(e=>e.id===id))return;M.addMessage(state,channel,sender,`${M.dateLabel({day:entry.day})} ${M.clock(entry.start)}–${M.clock(entry.end)} · ${M.ROOMS[entry.room].name}에서 ${entry.title}이 있습니다. ${entry.required?'준비할 내용을 확인해 주세요.':'가능하면 함께해 주세요. 참석 여부를 알려 주세요.'}`,{senderId:personId,appointment:{...entry,id,personId}});}
function parseInvitation(state,m){if(m.sender==='나'||!/회의|모임|수업 나눔|학습공동체|연수/.test(m.text))return null;const match=/전직원회의/.test(m.text)?m.text.match(/금요일\s*([01]?\d|2[0-3]):([0-5]\d)/):null;const time=match||m.text.match(/([01]?\d|2[0-3]):([0-5]\d)/);if(!time)return null;let day=m.day;const weekday=m.text.match(/(월|화|수|목|금)요일/);if(weekday)day=Math.floor(m.day/5)*5+['월','화','수','목','금'].indexOf(weekday[1]);if(/다음 주/.test(m.text))day+=5;else if(day<m.day)day+=5;const start=Number(time[1])*60+Number(time[2]);if(start<520||start>=1000)return null;const title=/전직원회의/.test(m.text)?'전직원회의':/학년회의/.test(m.text)?'학년회의':/수업 나눔|학습공동체/.test(m.text)?'수업 나눔 모임':'교직원 협의';return {title,day,start,end:Math.min(1000,start+20),room:title==='학년회의'?'research':'staff',type:'meeting',required:title==='전직원회의',personId:m.senderId|| (m.channel==='all'?'principal':'colleague')};}
export function sync(state){const d=data(state);for(const e of d.entries)if(e.title==='학년회의'&&live(e)&&(e.day>state.day||e.day===state.day&&e.end>state.minute)&&e.room!=='research'){e.room='research';M.addMessage(state,'grade','윤서진',M.dateLabel({day:e.day})+' '+M.clock(e.start)+' 학년회의 장소를 교사연구실로 변경했습니다. 개인 스케줄러에 반영했어요.',{senderId:'colleague',plannerScanned:true});}for(const m of state.messages)if(m.appointment?.title==='학년회의'&&!m.plannerScanned)m.appointment={...m.appointment,room:'research'};const week=Math.floor(state.day/5);if(!d.weeks[week]){d.weeks[week]=true;
 invitation(state,'all','한정우 교감','principal',{title:'전직원회의',day:week*5+4,start:930,end:950,room:'staff',type:'meeting',required:true});
 if(M.REGIONS[state.config.region].classes>1&&week%2===0&&state.day<=week*5+1)invitation(state,'grade','윤서진 선생님','colleague',{title:'학년회의',day:week*5+1,start:900,end:920,room:'research',type:'meeting',required:true});
 if(week%3===0&&state.day<=week*5+3)invitation(state,'grade','윤서진 선생님','colleague',{title:'수업 나눔 모임',day:week*5+3,start:960,end:980,room:'staff',type:'meeting',required:false});
 }
 for(const m of state.messages){if(m.plannerScanned)continue;m.plannerScanned=true;const entry=m.appointment||parseInvitation(state,m);if(entry&&entry.day>=0&&entry.day<M.demoDays(state)){const e=upsert(state,{...entry,source:'학교톡',sourceId:m.id});m.appointmentId=e.id;}}
 const p=state.schoolLife?.tutoring;if(p)for(let i=0;i<10;i++){const day=p.days?.[i]??(p.startWeek+i)*5+p.weekday,week=Math.floor(day/5),done=p.sessions.find(s=>s.week===week);upsert(state,{id:'tutoring-'+week,title:'기초학력지도 '+(i+1)+'회',day,start:900,end:940,room:'classroom',type:'tutoring',required:true,response:'참석',status:done?'완료':'예정',source:'지도 계획'});}
 for(const c of state.schoolLife?.counseling||[])upsert(state,{id:c.id,title:M.NPCS.find(n=>n.id===c.parentId)?.name||(state.students.find(s=>s.parentId===c.parentId)?.name||'전출 학생')+' 보호자 상담',day:c.day,start:c.minute,end:c.minute+20,room:'classroom',type:'counseling',required:true,response:'참석',personId:c.parentId,status:c.status==='완료'?'완료':c.status==='취소'?'취소':'예정',source:'상담 예약'});
 return d;
}
export function conflicts(state,day,start,end,exclude=null){return data(state).entries.filter(e=>e.id!==exclude&&e.type!=='task'&&live(e)&&e.response!=='불참'&&overlap(e,{day,start,end}));}
export function respond(state,id,choice){const e=data(state).entries.find(e=>e.id===id);if(!e||e.type!=='meeting'||e.status==='완료'||!['참석','불참'].includes(choice)||e.response===choice)return false;if(choice==='참석'&&conflicts(state,e.day,e.start,e.end,id).length)return {error:'이미 잡힌 일정과 겹칩니다. 먼저 일정을 조정해 주세요.'};e.response=choice;e.status=choice==='불참'?'불참':'예정';M.addMessage(state,e.personId==='principal'?'all':'grade','나',`${e.title} · ${M.dateLabel({day:e.day})} ${M.clock(e.start)} ${choice==='참석'?'참석하겠습니다.':'참석이 어렵습니다. 공유 자료를 부탁드립니다.'}`,{senderId:'teacher',recipientId:e.personId,appointmentReply:id});M.addMessage(state,e.personId==='principal'?'all':'grade',M.NPCS.find(n=>n.id===e.personId)?.name||'윤서진',choice==='참석'?'일정에 반영했습니다. 준비한 질문이 있으면 함께 나누어요.':'알겠습니다. 참석 여부와 관계없이 정리한 자료를 공유할게요.',{senderId:e.personId});return {ok:true};}
export function attend(state,id,note){const e=data(state).entries.find(e=>e.id===id);if(state.teacherDuty?.away||state.staffWork?.away)return {error:'휴가·출장에서 복귀 후에 참석해 주세요.'};if(!e||e.type!=='meeting'||!live(e)||e.response==='불참'||e.day!==state.day||state.minute>e.start||!['afternoon','specialist'].includes(M.currentSlot(state).kind))return {error:'예정일의 수업 후, 시작 시간 전에 참석을 준비해 주세요.'};if(M.todaySchedule(state).some(s=>!s.specialist&&s.start<e.end&&state.minute<s.end))return {error:'남아 있는 담임 수업을 마친 뒤 참석해 주세요.'};if(state.room!==e.room)return {error:M.ROOMS[e.room].name+'로 먼저 이동해 주세요.'};if(conflicts(state,e.day,e.start,e.end,id).length)return {error:'겹치는 상담이나 지도 일정을 먼저 조정해 주세요.'};M.advance(state,e.end-state.minute);e.status='완료';e.response='참석';e.note=String(note||'학생 관찰과 다음 활동 준비를 공유함.').slice(0,1000);e.completed=M.stamp(state);if(e.title==='전직원회의')M.complete(state,'meeting');if(e.title==='학년회의'){const a=GRADE_AGENDAS[e.agenda||'progress'];e.agenda??='progress';e.discussion=a.reply;upsert(state,{id:e.id+'-followup',title:a.task,day:Math.min(M.demoDays(state)-1,e.day+2),start:980,end:1000,room:'research',type:'task',source:'학년회의 후속 준비',personId:e.personId,originMeeting:e.id,response:'참석'});}M.addNote(state,'teacher',e.title+': '+e.note);M.log(state,e.title+' 참석 완료');M.addMessage(state,e.personId==='principal'?'all':'grade',M.NPCS.find(n=>n.id===e.personId)?.name||'윤서진',(e.discussion?e.discussion+' 후속 준비는 개인 스케줄러에도 남겼어요. ':'오늘 확인한 내용과 다음 준비 사항을 학교톡에 남깁니다. ')+e.note,{senderId:e.personId,plannerScanned:true});return {ok:true};}
export function addPersonal(state,title,day,start,end,room){if(!String(title).trim()||!Number.isInteger(day)||day<state.day||day>=M.demoDays(state)||!Number.isInteger(start)||!Number.isInteger(end)||start<520||end>1000||end<=start||day===state.day&&start<state.minute||!M.ROOMS[room])return {error:'제목과 앞으로의 근무 시간 안에 있는 일정을 확인해 주세요.'};if(M.todaySchedule({...state,day}).some(s=>!s.specialist&&s.start<end&&start<s.end)||conflicts(state,day,start,end).length)return {error:'담임 수업 또는 기존 일정과 겹칩니다.'};upsert(state,{id:'personal-'+Date.now(),title:String(title).trim().slice(0,80),day,start,end,room,type:'personal',required:false,response:'참석',source:'직접 기록'});return {ok:true};}
export function saveWorkPlan(state,job,goal,steps,deadline){const list=String(steps).split('\n').map(s=>s.trim()).filter(Boolean).slice(0,6);if(!M.SKILLS.includes(job)||!String(goal).trim()||!list.length||!Number.isInteger(deadline)||deadline<state.day||deadline>=M.demoDays(state))return false;const p={id:'work-'+data(state).workPlans.length,job,goal:String(goal).trim().slice(0,160),steps:list.map(text=>({text:text.slice(0,120),done:false})),deadline,created:M.stamp(state)};data(state).workPlans.push(p);upsert(state,{id:p.id,title:job+' 업무계획 점검',day:deadline,start:980,end:1000,room:'classroom',type:'task',source:'학기 초 계획',response:'참석'});return p;}
export function checkWorkStep(state,id,index){const p=data(state).workPlans.find(p=>p.id===id);if(!p?.steps[index])return false;p.steps[index].done=!p.steps[index].done;const e=data(state).entries.find(e=>e.id===id);if(e)e.status=p.steps.every(s=>s.done)?'완료':'예정';return true;}

export const GRADE_AGENDAS={
 progress:{name:'수업 진도 맞추기',question:'우리 반마다 진도가 조금 달라요. 어느 활동에 시간을 더 쓰면 좋을까요?',reply:'아이들이 어려워한 부분을 먼저 모아서, 다음 단원의 도입 자료를 함께 준비해요.',task:'학년 공통 진도와 보충 자료 정리'},
 assessment:{name:'수행평가 관찰 기준',question:'결과만 보지 않고 과정도 기록하려면 무엇을 같이 관찰할까요?',reply:'설명하기·협력하기·다시 시도하기를 나눠 보고, 관찰한 장면을 기준에 덧붙여요.',task:'수행평가 관찰 기준 초안 공유'},
 equipment:{name:'특별실·교구 사용',question:'다음 주 특별실과 공용 교구를 함께 쓰려면 어떤 준비가 필요할까요?',reply:'활동별 도구와 사용 순서를 먼저 적어 주세요. 겹치는 시간은 학교톡에서 조정해요.',task:'특별실 활용과 공용 교구 목록 정리'},
 participation:{name:'모두 참여하는 수업',question:'발표가 어렵거나 속도가 다른 아이들도 참여할 수 있는 방법을 나눌까요?',reply:'말·그림·짝 설명 중 고르게 하고, 기다리는 시간과 도움 요청 신호를 함께 정해요.',task:'다양한 참여 방법 수업안 보완'}
};
export function selectAgenda(state,id,agenda){const e=data(state).entries.find(e=>e.id===id);if(!e||e.title!=='학년회의'||!live(e)||!GRADE_AGENDAS[agenda]||e.agenda===agenda)return false;e.agenda=agenda;return true;}
export function completeFollowup(state,id,note){const e=data(state).entries.find(e=>e.id===id),origin=e&&data(state).entries.find(m=>m.id===e.originMeeting);if(!e||!origin||e.type!=='task'||!live(e)||origin.status!=='완료')return {error:'완료한 학년회의의 후속 준비를 선택해 주세요.'};if(state.room!=='research')return {error:'교사연구실에서 자료를 정리해 주세요.'};const slot=M.currentSlot(state);if(state.day<origin.day||!['afternoon','specialist'].includes(slot.kind)||Math.min(slot.end,1000)-state.minute<10||conflicts(state,state.day,state.minute,state.minute+10,id).length)return {error:'담임 수업과 약속이 없는 10분을 확보해 주세요.'};if(!String(note||'').trim())return {error:'함께 정리한 내용이나 다음 수업에 적용할 점을 적어 주세요.'};M.advance(state,10);e.note=String(note).trim().slice(0,1000);e.status='완료';e.completed=M.stamp(state);M.addNote(state,'teacher',e.title+': '+e.note);M.addMessage(state,'grade','나',e.title+' · '+e.note,{senderId:'teacher',plannerScanned:true});M.addMessage(state,'grade','윤서진','자료 확인했어요. 다음 수업에서 활용하고 아이들의 반응도 나누어요.',{senderId:'colleague',plannerScanned:true});state.npcRelations.colleague=M.clamp(state.npcRelations.colleague+1);M.log(state,e.title+' 완료 · 10분');return {ok:true};}
